/* app.js — الواجهة فقط: شاشات وأحداث، تستدعي core ودوال logic. لا مفاتيح سرية ولا وصول مباشر للتخزين. */


/* ---------- UI ---------- */
const $=s=>document.querySelector(s),esc=t=>String(t??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let core,S={tab:'cust',q:'',sel:new Set()},pickRes=null,persisted=null,pending=null;
const TY={text:'نص',number:'رقم',date:'تاريخ',list:'قائمة'},TR=['customers','visits','plans','orders','tasks'];
const toast=m=>{const t=$('#toast');t.textContent=m;t.className='show';setTimeout(()=>t.className='',2600)};
const openModal=h=>{$('#modal').innerHTML='<div>'+h+'</div>';$('#modal').className='on'};
const closeModal=()=>{$('#modal').className='';if(pickRes){pickRes(null);pickRes=null}};
const pick=(title,arr)=>new Promise(r=>{pickRes=r;openModal(`<h3>${title}</h3><select id=pk>${arr.map(x=>`<option>${esc(x)}</option>`).join('')}</select><div class=bar><button data-act=pkok>تطبيق</button><button class=sec data-act=close>إلغاء</button></div>`)});
const fdate=iso=>iso?new Date(iso).toLocaleString('ar-SA-u-ca-gregory',{dateStyle:'medium',timeStyle:'short'}):'—';

async function listHtml(){const all=await core.list('customers'),q=S.q.trim(),vm=vmap(await core.allVisits()),cad=await core.getS('cadence'),td=today();
 const L=all.filter(c=>!q||ct(c).includes(q.toLowerCase())).sort((x,y)=>x.name.localeCompare(y.name,'ar'));
 return`<div class=muted>${L.length} من ${all.length} عميل</div>`+(S.sel.size?`<div class=bar><span class=muted>محدد: ${S.sel.size}</span><button class=sec data-act=bulk data-k=status>الحالة</button><button class=sec data-act=bulk data-k=class>التصنيف</button><button class=sec data-act=bulk data-k=sector>القطاع</button><button class=danger data-act=bulk data-k=del>حذف</button><button class=sec data-act=selnone>إلغاء التحديد</button></div>`:`<button class=sec data-act=selall data-ids="${L.map(c=>c.id).join(',')}">تحديد الكل</button>`)
 +(L.map(c=>`<div class=row><input type=checkbox data-act=sel data-id=${c.id} ${S.sel.has(c.id)?'checked':''}><div class=t data-act=edit data-id=${c.id}><b>${esc(c.name)}</b><div class=muted>${esc([c.sector,c.district,c.phone].filter(Boolean).join(' · '))}</div></div><span class=muted>${esc([c.class,c.status].filter(Boolean).join(' / '))}${(()=>{const i=dueInfo(c,vm.get(c.id),cad,td);return i.kind==='never'?'<br><b style="color:#b45309">لم تُزَر</b>':i.late>0?'<br><b style="color:#b42318">متأخر '+i.late+' ي</b>':''})()}</span></div>`).join('')||'<p class=muted>لا يوجد عملاء. اضغط ＋ للإضافة.</p>')}
const views={
 cust:async()=>`<div class=bar><button class=sec data-act=impstart>استيراد Excel / CSV</button></div><input type=file id=impf accept=".xlsx,.csv,.tsv,.txt" hidden><input id=q placeholder="بحث بالاسم أو الجوال أو الحي" value="${esc(S.q)}"><div id=list>${await listHtml()}</div><button class=fab data-act=add>＋</button>`,
 trash:async()=>{let h='<h3>سلة المحذوفات</h3>',n=0;for(const s of TR){for(const r of await core.list(s,true)){n++;h+=`<div class=row><div class=t><b>${esc(r.name||r.id)}</b><div class=muted>${s} · حُذف ${fdate(r.deletedAt)}</div></div><button class=sec data-act=rst data-s=${s} data-id=${r.id}>استعادة</button><button class=danger data-act=prg data-s=${s} data-id=${r.id}>نهائي</button></div>`}}
  return h+(n?`<button class=danger data-act=empty>إفراغ السلة</button>`:'<p class=muted>السلة فارغة.</p>')},
 bk:async()=>{const b=await core.backupStatus(),ab=await core.autoList();
  return`<h3>النسخ الاحتياطي</h3><div class=warn style="border-radius:10px;text-align:right">النسخ التلقائية داخل المتصفح تضيع مع مسح بياناته أو حذف التطبيق. نزّل نسخة واحفظها خارج الجوال (Drive/واتساب/الحاسوب). التطبيق يسجّل وقت التنزيل ولا يستطيع التأكد من مكان حفظ الملف.</div><div class=row><div class=t>آخر نسخة: <b>${b.last?fdate(b.last):'لا توجد'}</b><div class=muted>التذكير كل ${b.days} أيام · حماية التخزين: ${persisted===null?'غير معروف':persisted?'مفعّلة':'غير مفعّلة'}</div></div></div>
  <div class=bar><button data-act=exp>تنزيل نسخة</button><button class=sec data-act=shr>مشاركة نسخة</button><button class=sec data-act=imp>استعادة من ملف</button></div><input type=file id=file accept=".json,application/json" hidden>
  <h3>نسخ تلقائية (آخر 3)</h3>`+(ab.map(o=>`<div class=row><div class=t>${fdate(o.at)}<div class=muted>${esc(o.why)} · عملاء: ${o.snap.counts.customers}</div></div><button class=sec data-act=abr data-id=${o.id}>استعادة</button></div>`).join('')||'<p class=muted>لا توجد بعد.</p>')},
 set:async()=>{const [co,rep,ti,bd]=await Promise.all(['company','rep','title','backupDays'].map(k=>core.getS(k)));
  let h=`<h3>بيانات التقارير</h3><label>اسم الشركة<input data-s=company value="${esc(co)}"></label><label>اسم المندوب<input data-s=rep value="${esc(rep)}"></label><label>المسمى الوظيفي<input data-s=title value="${esc(ti)}"></label><label>التذكير بالنسخ كل (أيام)<input data-s=backupDays type=number min=1 value="${bd}"></label>`;
  for(const[k,l]of[['sectors','القطاعات'],['districts','الأحياء'],['classes','التصنيفات'],['statuses','حالات العميل']]){const v=await core.getS(k);
   h+=`<h3>${l}</h3>`+v.map((x,i)=>`<span class=chip>${esc(x)} <b data-act=rml data-k=${k} data-i=${i}>✕</b></span>`).join('')+`<div class=bar><input id=n_${k} placeholder="إضافة"><button data-act=addl data-k=${k}>إضافة</button></div>`}
  const fs=await core.list('fields');
  return h+'<h3>حقول العميل المخصصة</h3>'+fs.map(f=>`<span class=chip>${esc(f.label)} (${TY[f.type]}) <b data-act=rmf data-id=${f.id}>✕</b></span>`).join('')+`<div class=g2><input id=fl placeholder="اسم الحقل"><select id=ft>${Object.entries(TY).map(([k,v])=>`<option value=${k}>${v}</option>`).join('')}</select></div><input id=fo placeholder="خيارات القائمة مفصولة بفاصلة"><div class=bar><button data-act=addf>إضافة حقل</button></div>`}};
async function render(){const b=await core.backupStatus();
 $('#app').innerHTML=(b.due?`<div class=warn>${b.last?'آخر نسخة نزّلتها قبل '+Math.floor(b.age)+' يوماً':'لم تنزّل نسخة احتياطية بعد'}${b.changes?' · '+b.changes+' تعديلاً غير محفوظ خارج التطبيق':''}. احفظ الملف خارج المتصفح (Drive/واتساب/الحاسوب). <a href=# data-act=tab data-k=bk>انسخ الآن</a></div>`:'')+'<main>'+await views[S.tab]()+'</main><nav>'+[['cust','العملاء'],['map','الخريطة'],['plan','الخطة'],['orders','الطلبيات'],['dash','الأداء'],['more','المزيد']].map(([k,l])=>`<button data-act=tab data-k=${k} class="${S.tab===k||(k==='more'&&['cov','rep','trash','bk','set'].includes(S.tab))?'on':''}">${l}</button>`).join('')+'</nav>';if(S.tab==='map')initMap()}
async function openForm(id){const c=id?await core.get('customers',id):{},[sec,dis,cls,sta]=await Promise.all(['sectors','districts','classes','statuses'].map(k=>core.getS(k))),cf=(await core.list('fields')).filter(f=>f.entity==='customers');
 const sel=(n,arr,v)=>`<select name=${n}><option value="">—</option>${[...arr,...(v&&!arr.includes(v)?[v]:[])].map(x=>`<option${x===v?' selected':''}>${esc(x)}</option>`).join('')}</select>`,cv=c.custom||{};
 openModal(`<form id=f data-id="${id||''}"><h3>${id?'تعديل عميل':'عميل جديد'}</h3><label>اسم المحل *<input name=name value="${esc(c.name)}"></label><div class=g2><label>رقم العميل<input name=code value="${esc(c.code)}"></label><label>الجوال<input name=phone inputmode=tel value="${esc(c.phone)}"></label></div>
 <div class=g2><label>القطاع${sel('sector',sec,c.sector)}</label><label>الحي<input name=district list=dl value="${esc(c.district)}"><datalist id=dl>${dis.map(x=>`<option>${esc(x)}</option>`).join('')}</datalist></label></div>
 <label>العنوان<input name=address value="${esc(c.address)}"></label><div class=g2><label>خط العرض<input name=lat inputmode=decimal value="${esc(c.lat)}"></label><label>خط الطول<input name=lng inputmode=decimal value="${esc(c.lng)}"></label></div>
 <div class=g2><label>التصنيف${sel('class',cls,c.class)}</label><label>الحالة${sel('status',sta,c.status)}</label></div><div class=g2><label>دورية الزيارة (أيام)<input name=freq inputmode=numeric list=fq placeholder="افتراضي حسب التصنيف" value="${esc(c.freq)}"><datalist id=fq><option>7<option>14<option>30</datalist></label><label>ألصق رابط Google Maps<input name=maplink placeholder="لتعبئة الإحداثيات"></label></div><label>ملاحظات<textarea name=notes rows=3>${esc(c.notes)}</textarea></label>
 ${cf.map(f=>`<label>${esc(f.label)}`+(f.type==='list'?`<select name="cf_${f.id}"><option value="">—</option>${(f.options||[]).map(o=>`<option${o===cv[f.id]?' selected':''}>${esc(o)}</option>`).join('')}</select>`:`<input name="cf_${f.id}" type=${f.type==='number'?'text':f.type} ${f.type==='number'?'inputmode=decimal':''} value="${esc(cv[f.id])}">`)+'</label>').join('')}
 <div class=bar><button type=submit>حفظ</button>${id?'<button type=button class=sec data-act=chist data-id='+id+'>الزيارات والطلبيات</button><button type=button class=sec data-act=onew data-id='+id+'>طلبية جديدة</button>':''}${id?'<button type=button class=danger data-act=delone>حذف</button>':''}<button type=button class=sec data-act=close>إلغاء</button></div></form>`)}
document.addEventListener('submit',async e=>{e.preventDefault();const f=e.target;if(f.id!=='f')return;const id=f.dataset.id,fd=new FormData(f),d={custom:{}};
 for(const[k,v]of fd.entries()){if(k.startsWith('cf_'))d.custom[k.slice(3)]=v;else d[k]=v}
 if(d.maplink&&d.maplink.trim()){const ll=linkLatLng(d.maplink);if(!ll)return toast('تعذر استخراج الإحداثيات من الرابط (الروابط المختصرة تحتاج إنترنت)');d.lat=ll[0];d.lng=ll[1]}delete d.maplink;
 d.freq=String(d.freq||'').trim()===''?null:Number(dig(d.freq));if(d.freq!==null&&!(d.freq>=1&&d.freq<=365))return toast('دورية الزيارة بين 1 و365 يوماً');
 let r=id?await core.update('customers',id,d):await core.create('customers',d);
 if(r.err==='duplicate'){if(!confirm('يوجد عميل بنفس الجوال: '+r.dup.name+'. حفظ مع ذلك؟'))return;r=await core.create('customers',d,true)}
 if(r.err)return toast(r.err);
 if(d.district){const l=await core.getS('districts');if(!l.includes(d.district)){l.push(d.district);await core.setS('districts',l)}}
 closeModal();toast('تم الحفظ');render()});
async function doExport(share){const sn=await core.exportBackup(),name='backup-'+sn.createdAt.slice(0,10)+'.json',file=new File([JSON.stringify(sn)],name,{type:'application/json'});
 if(share&&navigator.canShare&&navigator.canShare({files:[file]})){try{await navigator.share({files:[file]})}catch{}}
 else{const u=URL.createObjectURL(file),l=document.createElement('a');l.href=u;l.download=name;l.click();setTimeout(()=>URL.revokeObjectURL(u),5000)}render()}
async function doRestore(o){const r=await core.restoreBackup(o);closeModal();if(r.err)toast(r.err);else{S.sel.clear();toast('تمت الاستعادة');render()}}
document.addEventListener('click',async e=>{const t=e.target.closest('[data-act]');if(!t)return;const d=t.dataset,A=d.act;if(A==='tab')e.preventDefault();
 if(A==='tab'){S.tab=d.k;S.sel.clear();return render()}
 if(A==='close')return closeModal();
 if(A==='pkok'){const v=$('#pk').value,r=pickRes;pickRes=null;closeModal();return r&&r(v)}
 if(A==='add')return openForm();
 if(A==='edit')return openForm(d.id);
 if(A==='sel'){t.checked?S.sel.add(d.id):S.sel.delete(d.id);return render()}
 if(A==='selall'){d.ids.split(',').filter(Boolean).forEach(i=>S.sel.add(i));return render()}
 if(A==='selnone'){S.sel.clear();return render()}
 if(A==='delone'){const id=$('#f').dataset.id;if(!confirm('حذف هذا العميل؟ سينتقل إلى السلة.'))return;await core.remove('customers',id);closeModal();toast('نُقل إلى السلة');return render()}
 if(A==='bulk'){const ids=[...S.sel];if(d.k==='del'){if(!confirm('حذف '+ids.length+' عميل؟ ستنقل إلى السلة وتُنشأ نسخة تلقائية.'))return;await core.remove('customers',ids)}
  else{const v=await pick('اختر القيمة',await core.getS({status:'statuses',class:'classes',sector:'sectors'}[d.k]));if(v===null)return;await core.bulk('customers',ids,{[d.k]:v})}
  S.sel.clear();toast('تم');return render()}
 if(A==='rst'){await core.restore(d.s,d.id);toast('تمت الاستعادة');return render()}
 if(A==='prg'){if(!confirm('حذف نهائي؟ لا يمكن التراجع (تُنشأ نسخة تلقائية قبله).'))return;await core.purge(d.s,d.id);return render()}
 if(A==='empty'){if(!confirm('إفراغ السلة نهائياً؟'))return;for(const s of TR){const ids=(await core.list(s,true)).map(r=>r.id);if(ids.length)await core.purge(s,ids)}return render()}
 if(A==='exp')return doExport(false);if(A==='shr')return doExport(true);
 if(A==='imp'){const fi=$('#file');fi.value='';fi.click();return}
 if(A==='abr'){const o=(await core.autoList()).find(x=>x.id===d.id);if(o&&confirm('استعادة هذه النسخة؟ ستُنشأ نسخة بحالتك الحالية أولاً.'))doRestore(o.snap);return}
 
 if(A==='addl'){const v=$('#n_'+d.k).value.trim();if(!v)return;const l=await core.getS(d.k);if(l.includes(v))return toast('موجود مسبقاً');l.push(v);await core.setS(d.k,l);return render()}
 if(A==='addf'){const label=$('#fl').value.trim(),type=$('#ft').value,options=$('#fo').value.split(/[,،]/).map(x=>x.trim()).filter(Boolean);if(!label)return toast('اكتب اسم الحقل');if(type==='list'&&!options.length)return toast('أضف خيارات للقائمة');await core.create('fields',{entity:'customers',label,type,options});return render()}
 if(A==='rmf'){if(confirm('حذف الحقل؟ قيمه المخزنة تبقى في النسخ لكنها لن تظهر.')){await core.delField(d.id);render()}}});
document.addEventListener('change',async e=>{const t=e.target;
 if(t.id==='file'&&t.files[0]){let o;try{o=JSON.parse(await t.files[0].text())}catch{return toast('الملف غير صالح')}const err=core.check(o);if(err)return toast(err);pending=o;
  openModal(`<h3>نسخة سليمة</h3><p>تاريخها: ${fdate(o.createdAt)}<br>عملاء: ${o.counts.customers} · زيارات: ${o.counts.visits} · طلبيات: ${o.counts.orders}</p><p class=muted>ستحل محل بياناتك الحالية، وتُنشأ نسخة تلقائية بها أولاً.</p><div class=bar><button class=danger data-act=rok>استعادة</button><button class=sec data-act=close>إلغاء</button></div>`)}
 if(t.dataset.s){const k=t.dataset.s;await core.setS(k,k==='backupDays'||k==='dayCap'||k==='reactDays'?Math.max(1,Number(t.value)||(k==='dayCap'?12:k==='reactDays'?90:7)):t.value.trim());toast('تم الحفظ')}});
document.addEventListener('click',e=>{if(e.target.closest('[data-act=rok]')&&pending){const o=pending;pending=null;doRestore(o)}});
document.addEventListener('input',async e=>{if(e.target.id==='q'){S.q=e.target.value;$('#list').innerHTML=await listHtml()}});
/* ---------- المرحلة 2: استيراد، خريطة، تغطية ---------- */
let IMP=null,PLAN=null,MS={z:11,c:[24.7136,46.6753],fit:false},MF={q:'',sector:'',class:'',status:'',tiles:false},MV=[],SELID=null,MD=null;
const PAL=['#16a34a','#6b7280','#d97706','#dc2626','#7c3aed','#0891b2'],TC=new Map();
const ct=c=>[c.name,c.code,c.phone,c.district,c.sector,c.address,c.group,c.notes,...Object.values(c.custom||{})].join(' ').toLowerCase();
const nat=(a,b)=>a.localeCompare(b,'ar',{numeric:true});
const grpOf=all=>{const m=new Map();all.filter(c=>c.group).forEach(c=>{if(!m.has(c.group))m.set(c.group,[]);m.get(c.group).push(c)});m.forEach(l=>l.sort((x,y)=>(x.order||0)-(y.order||0)));return[...m.entries()].sort((x,y)=>nat(x[0],y[0]))};
async function loadImport(f){try{const n=f.name.toLowerCase();let rows;
 if(n.endsWith('.xlsx'))rows=await xlsxRows(await f.arrayBuffer());else if(n.endsWith('.xls'))return toast('صيغة xls القديمة غير مدعومة: احفظ الملف بصيغة xlsx أو csv');else rows=parseCSV(await f.text());
 if(rows.length<2)return toast('الملف لا يحتوي بيانات');IMP={headers:rows[0].map(x=>x.trim()),rows:rows.slice(1)};IMP.map=mapCols(IMP.headers);showMapping()}catch(x){toast('تعذرت قراءة الملف: '+x.message)}}
function showMapping(){const opt=m=>'<option value="">—</option>'+IMP.headers.map((h,i)=>`<option value=${i}${m===i?' selected':''}>${esc(h||'عمود '+(i+1))}</option>`).join('');
 openModal(`<h3>مطابقة الأعمدة</h3><p class=muted>${IMP.rows.length} سطر. تأكد من ربط كل حقل بالعمود الصحيح (الورقة الأولى فقط تُقرأ).</p>`+Object.entries(FN).map(([f,l])=>`<label>${l}${f==='name'?' *':''}<select data-im=${f}>${opt(IMP.map[f])}</select></label>`).join('')+`<div class=bar><button data-act=ianalyze>تحليل وفحص التكرار</button><button class=sec data-act=close>إلغاء</button></div>`)}
function showReview(){const I=IMP.items,k=x=>I.filter(i=>i.kind===x),nw=k('new'),mt=I.filter(i=>i.kind==='exact'||i.kind==='similar'||i.kind==='filedup'),iv=k('invalid');
 const sel=it=>{const o=it.kind==='filedup'?[['skip','تخطي'],['add','إضافة كجديد']]:[['skip','تخطي'],['fill','تعبئة الفارغ فقط'],['over','استبدال ببيانات الملف'],['add','إضافة كجديد']];return`<select data-ii=${I.indexOf(it)}>${o.map(([v,l])=>`<option value=${v}${it.action===v?' selected':''}>${l}</option>`).join('')}</select>`};
 const card=it=>{const m=it.match,d=it.diff&&Object.keys(it.diff).length?Object.entries(it.diff).map(([f,[o,n]])=>`${FN[f]}: ${esc(o||'—')} ← ${esc(n)}`).join('<br>'):'';
  return`<div class=row style="display:block"><b>سطر ${it.i}: ${esc(it.rec.name)}</b> <span class=muted>(${it.kind==='filedup'?esc(it.why):(it.kind==='exact'?'متطابق':'مشابه')+' حسب '+esc(it.why)})</span>${m?`<div class=muted>الموجود: ${esc(m.name)} ${esc(m.phone||'')}</div>`:''}${d?`<div class=muted>${d}</div>`:''}${sel(it)}</div>`};
 openModal(`<h3>مراجعة الاستيراد</h3><p>جديد: <b>${nw.length}</b> · متطابق/مشابه: <b>${mt.length}</b> · غير صالح: <b>${iv.length}</b></p><p class=muted>القرار الافتراضي للمتطابق: تخطي. لن يُكتب فوق أي بيانات دون اختيارك.</p><p class=muted>نسخة احتياطية تلقائية تُنشأ قبل الاعتماد.</p>`
 +(nw.length?`<p class=muted>سيُضاف: ${nw.slice(0,6).map(i=>esc(i.rec.name)).join('، ')}${nw.length>6?' …':''}</p>`:'')
 +(iv.length?`<details><summary>سطور مرفوضة (${iv.length})</summary>${iv.map(i=>`<div class=muted>سطر ${i.i}: ${esc(i.rec.name||'—')} — ${esc(i.why)}</div>`).join('')}</details>`:'')
 +(mt.length?`<div class=bar><button class=sec data-act=iskip>تخطي كل المتطابقات</button></div>`+mt.map(card).join(''):'')
 +`<div class=bar><button data-act=iapply>اعتماد الاستيراد</button><button class=sec data-act=close>إلغاء</button></div>`)}
