 if(t.name==='outcome'){const f=(D.f||'').includes('f');$('#fl').style.display=f?'block':'none';if(f){const i=$('#fl input');if(!i.value)i.value=addDays(today(),3)}}
 if(t.id==='pdate'&&t.value){S.pd=t.value;render()}
 if(D.oi!==undefined){const oc=await core.getS('outcomes');oc[+D.oi][D.fl]=t.checked?1:0;await core.setS('outcomes',oc)}
 if(D.cd){const cad=await core.getS('cadence');cad[D.cd]={...(cad[D.cd]||{days:28,w:10}),[D.cf]:Math.max(D.cf==='days'?1:0,Number(t.value)||0)};await core.setS('cadence',cad);toast('تم الحفظ')}
 if(D.wt){const w={...DEFW,...await core.getS('weights')};w[D.wt]=Math.max(0,Number(t.value)||0);await core.setS('weights',w);toast('تم الحفظ')}
 if(D.wd!==undefined){let w=await core.getS('workdays');w=t.checked?[...new Set([...w,+D.wd])]:w.filter(x=>x!==+D.wd);await core.setS('workdays',w)}
