 if(A==='wgen'){const cp=await core.getS('dayCap'),wd=await core.getS('workdays');let any=false;for(let i=0;i<7;i++)if(await core.getPlan(addDays(S.pd,i)))any=true;if(any&&!confirm('توجد خطط في هذا الأسبوع: سيُستبدل غير المنفذ وغير اليدوي. متابعة؟'))return;const r=await core.planWeek(S.pd,cp,wd);toast('أُنشئت/حُدّثت خطط '+r.length+' أيام');return render()}
 if(A==='pmv'){await core.planMove(S.pd,d.id,+d.d);return render()}
