const irow=(it,i,dis)=>`<div class=row style="display:block" data-ir=${i}><input data-f=name placeholder="المنتج" value="${esc(it.name)}" ${dis?'disabled':''}><div class=g2 style="margin-top:6px"><input data-f=qty inputmode=decimal placeholder="الكمية" value="${esc(it.qty)}" ${dis?'disabled':''}><input data-f=price inputmode=decimal placeholder="سعر الوحدة (ر.س)" value="${esc(it.price)}" ${dis?'disabled':''}></div><input data-f=discount inputmode=decimal placeholder="خصم البند (ر.س)" value="${esc(it.discount||'')}" style="margin-top:6px" ${dis?'disabled':''}></div>`;
function recalc(){const f=$('#of');if(!f)return;let s=0;f.querySelectorAll('#irows [data-ir]').forEach(r=>{const g=k=>r.querySelector(`[data-f=${k}]`).value;s+=(NUM(g('qty'))||0)*(NUM(g('price'))||0)-(g('discount').trim()?NUM(g('discount')):0)});const d=f.querySelector('[name=discount]').value.trim();$('#otot').textContent=money(s-(d?NUM(d):0))}
