async function orderView(id){const o=await core.get('orders',id);if(!o)return;const c=await core.get('customers',o.customerId),al=orderAlerts(o,today(),await core.getS('orderTh')),tasks=(await core.allTasks()).filter(t=>t.orderId===id),v=o.visitId?await core.get('visits',o.visitId):null,term=TERMINAL.includes(o.status),i=stIdx(o.status),tot=calcTotals(o.items,o.discount);
 const stg=o.timeline.filter(e=>e.kind==='stage'),reached=i>=0?i:Math.max(...stg.map(e=>stIdx(e.to))),dateOf=k=>{const e=[...stg].reverse().find(e=>e.to===k);return e?fdate(e.at):''};
 openModal(`<h3>${esc(o.no)} · ${esc(c?c.name:'—')}</h3><div class=muted>${c&&c.phone?`<a href="tel:${esc(c.phone)}">${esc(c.phone)}</a> · `:''}سُجّلت ${fdate(o.createdAt)}${o.expectedDate?' · تسليم متوقع '+o.expectedDate:''}</div>
 <p><b>${stName(o.status)}</b>${o.stalled?' <span class=tag>متعثرة</span>':''} · الإجمالي <b>${money(o.total)}</b></p>${al.map(a=>`<div class=tag>${esc(a.text)}</div>`).join('')}
 ${v?`<div class=muted>الزيارة: ${v.date} · ${esc(v.outcome)} <button class=sec style="min-height:32px" data-act=vedit data-id=${v.id}>فتح</button></div>`:''}
 <div style="margin:8px 0">${STAGES.map((s,k)=>`<div class="sg ${k<=reached&&stg.some(e=>e.to===s.k)?'done':''} ${k===i?'cur':''}"><i></i><span>${s.n}</span><span class=muted style="margin-inline-start:auto">${dateOf(s.k)}</span></div>`).join('')}</div>
 ${o.carrier?`<div class=muted>الشحن: ${esc(o.carrier)}${o.tracking?' · رقم التتبع '+esc(o.tracking):''}${o.expectedArrival?' · وصول متوقع '+o.expectedArrival:''}</div>`:''}
 ${!term?`<div class=bar><button data-act=ostage data-id=${id}>تأكيد: ${ACT[i+1]}</button></div>`:''}
 <div class=bar>${!term?`<button class=sec data-act=oedit data-id=${id}>تعديل</button><button class=sec data-act=ostall data-id=${id}>${o.stalled?'رفع التعثر':'تعثّرت'}</button><button class=sec data-act=otask data-id=${id}>مهمة متابعة</button>${i>0?`<button class=sec data-act=orb data-id=${id}>تصحيح: تراجع مرحلة</button>`:''}<button class=danger data-act=ocancel data-id=${id}>إلغاء الطلبية</button>`:''}${o.status!=='cancelled'&&o.status!=='returned'&&i>=5?`<button class=danger data-act=oret data-id=${id}>إرجاع</button>`:''}<button class=sec data-act=onote data-id=${id}>إضافة ملاحظة</button></div>
 <h4>البنود</h4><table><tr><th>المنتج</th><th>الكمية</th><th>السعر (ر.س)</th><th>الخصم</th></tr>${o.items.map(x=>`<tr><td>${esc(x.name)}</td><td>${x.qty}</td><td>${x.price}</td><td>${x.discount||0}</td></tr>`).join('')}</table><div class=muted>المجموع ${money(tot.sub)} · خصم البنود ${money(tot.lineDisc)} · خصم الطلبية ${money(tot.discount)} · <b>الإجمالي ${money(tot.total)}</b></div>${o.notes?`<p>ملاحظات: ${esc(o.notes)}</p>`:''}
 ${tasks.length?'<h4>مهام المتابعة</h4>'+tasks.map(t=>`<div class=row><div class=t><b>${esc(t.title)}</b><div class=muted>${t.due} · ${{open:'مفتوحة',done:'أُنجزت',cancelled:'أُغلقت'}[t.status]}${t.result?' · '+esc(t.result):''}</div></div>${t.status==='open'?`<button data-act=tdone data-id=${t.id}>إنجاز</button>`:''}</div>`).join(''):''}
 <h4>السجل الزمني (${o.timeline.length})</h4>${[...o.timeline].reverse().map(e=>`<div class=row style="display:block"><b>${tlLabel(e)}</b> <span class=muted>${fdate(e.at)}</span><div class=muted>${tlDetail(e)} · بواسطة ${esc(e.by)} (${esc(e.src)}) · سُجّل ${fdate(e.loggedAt)}</div></div>`).join('')}<div class=bar><button class=sec data-act=close>إغلاق</button></div>`)}
async function ordersListHtml(){const[os,cs]=await Promise.all([core.allOrders(),core.list('customers')]),cm=new Map(cs.map(c=>[c.id,c])),th=await core.getS('orderTh'),td=today();
 const L=os.map(o=>({o,al:orderAlerts(o,td,th),c:cm.get(o.customerId)})).filter(({o,al,c})=>{if(OF.q&&!((c?c.name:'')+' '+o.no).toLowerCase().includes(OF.q.toLowerCase()))return false;if(OF.st==='open'&&TERMINAL.includes(o.status))return false;if(OF.st==='late'&&!al.length)return false;
  if(OF.st&&OF.st!=='open'&&OF.st!=='late'&&o.status!==OF.st)return false;if(OF.from&&o.date<OF.from)return false;if(OF.to&&o.date>OF.to)return false;if(OF.sector&&(!c||c.sector!==OF.sector))return false;return true}).sort((x,y)=>y.o.createdAt.localeCompare(x.o.createdAt));
 return`<div class=muted>${L.length} من ${os.length} طلبية</div>`+(L.map(({o,al,c})=>`<div class=row data-act=oopen data-id=${o.id}><div class=t><b>${esc(o.no)} · ${esc(c?c.name:'—')}</b><div class=muted>${o.date} · ${money(o.total)} · <b>${stName(o.status)}</b>${o.stalled?' · متعثرة':''}</div>${al.map(a=>`<span class=tag>${esc(a.text)}</span>`).join('')}</div><span class=muted>›</span></div>`).join('')||'<p class=muted>لا طلبيات مطابقة.</p>')}
